// ClientEvent A single client-side telemetry event. JoinInitiated is the top-level marker emitted when a user begins a join attempt and carries only join_attempt_id (no stage_id or coordinator_connect_id). When stage is CoordinatorJoin, CoordinatorWS, WSJoin, or PeerConnectionConnect the event reports a join-lifecycle attempt; initiation and completion of a stage attempt share the same stage_id. FirstAudioFrame and FirstVideoFrame report media readiness and only ever carry an initiated event. MediaDevicePermission reports the result of requesting screen-share, microphone, and camera permissions. Other stage values denote generic client events.
type ClientEvent struct {
	// CallSessionID Call session ID associated with the attempt. Required on every event except CoordinatorJoin initiation and CoordinatorJoin failure (where the call session is not yet established); optional on MediaDevicePermission.
	CallSessionID *string `json:"call_session_id,omitempty"`

	// CameraPermissionStatus Camera permission status: INITIATED, FAILED, GRANTED, or NOT_INITIATED. Required on every MediaDevicePermission event.
	CameraPermissionStatus *string `json:"camera_permission_status,omitempty"`

	// CoordinatorConnectID UUID generated by the client and shared across every event of the same coordinator connection. Required on every event except JoinInitiated, which is reported before a coordinator connection exists.
	CoordinatorConnectID *string `json:"coordinator_connect_id,omitempty"`

	// ElapsedTime Milliseconds elapsed between the stage attempt's initiation and this event.
	ElapsedTime *int64 `json:"elapsed_time,omitempty"`

	// EventType Whether the event marks the start (initiated) or resolution (completed) of a stage attempt, or another event-specific value
	EventType *string `json:"event_type,omitempty"`

	// IceState Terminal state of the peer connection. Required on PeerConnectionConnect failure.
	IceState *string `json:"ice_state,omitempty"`

	// ID Call ID associated with the event. Required on every stage except CoordinatorWS, where it is optional.
	ID *string `json:"id,omitempty"`

	// JoinAttemptID UUID generated by the client and shared across JoinInitiated and the join-lifecycle events (CoordinatorJoin, WSJoin, PeerConnectionConnect) of the same overall join attempt. Required on every join event except CoordinatorWS, which is reported before a join attempt is established.
	JoinAttemptID *string `json:"join_attempt_id,omitempty"`

	// JoinReason Reason the client initiated the join. Optional on CoordinatorJoin events; empty when not provided.
	JoinReason *string `json:"join_reason,omitempty"`

	// MicrophonePermissionStatus Microphone permission status: INITIATED, FAILED, GRANTED, or NOT_INITIATED. Required on every MediaDevicePermission event.
	MicrophonePermissionStatus *string `json:"microphone_permission_status,omitempty"`

	// Outcome Resolution of a completed event: success or failure. Required on completed join events; forbidden on initiated join events.
	Outcome *string `json:"outcome,omitempty"`

	// PeerConnection Which peer connection a PeerConnectionConnect event reports on: publish or subscribe. Required on every PeerConnectionConnect event.
	PeerConnection *string `json:"peer_connection,omitempty"`

	// PreviouslyConnectedTimestamp UTC timestamp at which the ICE connection was established earlier in the session, when applicable
	PreviouslyConnectedTimestamp *Time `json:"previously_connected_timestamp,omitempty"`

	// RetryCountAttempt Total in-stage retries the client made before resolving (0–1000). Required on completed join events.
	RetryCountAttempt *int32 `json:"retry_count_attempt,omitempty"`

	// RetryFailureCode Failure code string. Required on CoordinatorJoin, CoordinatorWS, WSJoin, and PeerConnectionConnect failure.
	RetryFailureCode *string `json:"retry_failure_code,omitempty"`

	// RetryFailureReason Failure reason string. Required on CoordinatorJoin, CoordinatorWS, WSJoin, and PeerConnectionConnect failure.
	RetryFailureReason *string `json:"retry_failure_reason,omitempty"`

	// ScreenShareStatus Screen-share permission status: INITIATED, FAILED, GRANTED, or NOT_INITIATED. Optional on MediaDevicePermission events.
	ScreenShareStatus *string `json:"screen_share_status,omitempty"`

	// SdkVersion Version of the client SDK
	SdkVersion *string `json:"sdk_version,omitempty"`

	// SfuID Identifier of the SFU the client was attempting to connect to. Required on WSJoin and PeerConnectionConnect failure, and on FirstAudioFrame and FirstVideoFrame.
	SfuID *string `json:"sfu_id,omitempty"`

	// Stage Discriminator identifying the event kind. JoinInitiated marks the start of a join attempt; join-lifecycle events use CoordinatorJoin, CoordinatorWS, WSJoin, or PeerConnectionConnect; media-readiness events use FirstAudioFrame or FirstVideoFrame; MediaDevicePermission reports device permission results; other values denote generic client events.
	Stage *string `json:"stage,omitempty"`

	// StageID UUID generated by the client at initiation. Identical on the matching completion event. Absent on JoinInitiated.
	StageID *string `json:"stage_id,omitempty"`

	// Timestamp UTC timestamp at which the event was recorded
	Timestamp *Time `json:"timestamp,omitempty"`

	// TrackID Identifier of the media track the frame belongs to. Required on FirstVideoFrame; optional on FirstAudioFrame.
	TrackID *string `json:"track_id,omitempty"`

	// Type Call type associated with the event. Required on every stage except CoordinatorWS, where it is optional.
	Type *string `json:"type,omitempty"`

	// UserAgent User agent string of the client SDK
	UserAgent *string `json:"user_agent,omitempty"`

	// UserID ID of the user the event was recorded for
	UserID *string `json:"user_id,omitempty"`

	// WasPreviouslyConnected Whether the ICE connection had been established earlier in the same session. Required on every PeerConnectionConnect event so reconnects can be distinguished from fresh connects.
	WasPreviouslyConnected *bool `json:"was_previously_connected,omitempty"`
}

